import { Directive, ElementRef, input, Renderer2 } from '@angular/core';

@Directive({
  selector: '[appHighlightLegendaryPokemon]',
})
export class HighlightLegendaryPokemonDirective {
  readonly appHighlightLegendaryPokemon = input<boolean>();
  constructor(private el: ElementRef, private renderer: Renderer2) {}

  ngOnInit(): void {
    const isLegendary = this.appHighlightLegendaryPokemon();
    if (isLegendary) {
      this.renderer.setStyle(
        this.el.nativeElement,
        'boxShadow',
        '0 0 15px 5px gold'
      );
      this.renderer.setStyle(this.el.nativeElement, 'borderRadius', '15px');
      this.renderer.setStyle(this.el.nativeElement, 'display', 'inline-block');
    }
  }
}

import {
  Directive,
  ElementRef,
  HostListener,
  inject,
  Renderer2,
} from '@angular/core';

@Directive({
  selector: '[appHighlightOverflowingContent]',
})
export class HighlightOverflowingContentDirective {
  private el = inject(ElementRef);
  private renderer = inject(Renderer2);

  ngAfterViewInit() {
    this.checkOverflow();
  }

  @HostListener('window:resize')
  onResize() {
    this.checkOverflow();
  }

  private checkOverflow(): void {
    if (this.el.nativeElement.clientWidth < this.el.nativeElement.scrollWidth) {
      this.renderer.setStyle(this.el.nativeElement, 'background', 'red');
    } else {
      this.renderer.removeStyle(this.el.nativeElement, 'background');
    }
  }
}

